import { PRINT_SHEET } from '../content/intro.ts';
import { h } from './dom.ts';

/**
 * The all-in-one code: a QR code with the AR marker in its middle. A phone
 * camera reads the QR and opens the AR page, and that page recognises the
 * square in the middle. Generated by tools/make-nested-marker.ts.
 */
const CODE_URL = `${import.meta.env.BASE_URL}ar/pal-marker.png`;

/** The surprise itself, used both on paper and in the on-screen fallback. */
export function surprise(): HTMLElement {
  const code = h('img', { class: 'surprise__code', attrs: { src: CODE_URL, alt: PRINT_SHEET.codeAlt } });
  // A missing file should leave a gap, not a broken-image icon on paper.
  code.addEventListener('error', () => {
    code.hidden = true;
  });
  return h('figure', { class: 'surprise' }, code, h('figcaption', { class: 'surprise__caption', text: PRINT_SHEET.caption }));
}

/**
 * Opens the browser's own print dialog with only the surprise on the page.
 * The dialog is the real one, and a page cannot tell whether it ended in
 * "Print" or "Cancel": `onClosed` only means the dialog is gone.
 */
export function printSurprise(onClosed: () => void): void {
  const sheet = h('div', { class: 'print-sheet' }, surprise());
  document.body.append(sheet);

  let closed = false;
  const finish = (): void => {
    if (closed) return;
    closed = true;
    window.removeEventListener('afterprint', finish);
    sheet.remove();
    onClosed();
  };
  window.addEventListener('afterprint', finish);
  window.print();
  // Some mobile browsers return at once and never fire `afterprint`.
  window.setTimeout(finish, 1500);
}
